#Requires -Version 5.1
# fix-planificador-optimizar-espacio-visual.ps1
#
# IMPLEMENTACION (solo cambios visuales/maquetacion, ninguna logica funcional):
#
# 1. src/app/planificacion/page.tsx (MODIFICADO)
#
#    a) ObraRow (Vista Obras): nombre y estado de la obra en la misma linea
#       - Contenedor pasa de apilado (Link block + select debajo) a flex
#         en fila: Link con flex-1 min-w-0 truncate + title=nombre completo
#         (tooltip), select de estado con shrink-0 max-w-[86px] truncate
#         whitespace-nowrap + title con el nombre del estado.
#       - Se mantiene el color del estado via style={{ color: ... }}.
#       - Padding vertical reducido (py-3->py-2 en el grip, py-1.5->py-1
#         en el contenedor de nombre+estado).
#       - onChangeEstado, onAddManual, onArchive: SIN CAMBIOS de logica.
#
#    b) Altura de fila reducida de forma consistente
#       - min-h-[44px] -> min-h-[36px] en la celda de dia de ObraRow y en
#         la fila virtual SIN ASIGNAR (SinAsignarRow), para que toda la
#         rejilla de Vista Obras mantenga alturas coherentes.
#       - No se toco Vista Personas (RrhhCell/SortablePersonRow) ni la
#         vista movil: fuera del alcance solicitado.
#
#    c) Cabecera y navegacion compactadas
#       - Header (titulo + selector Vista Obras/Personas) y Nav (navegacion
#         de semana/mes/año + filtros + botones) se agrupan en una sola
#         barra flex-wrap (antes eran dos bloques con mb-2 y mb-1.5 fijos).
#       - flex-wrap permite que en pantallas estrechas los controles pasen
#         a una segunda linea automaticamente, SIN scroll horizontal y sin
#         ocultar ningun boton.
#       - Iconos, paddings y textos reducidos ligeramente (p.ej. py-1 ->
#         py-0.5 en botones, w-8 h-8 -> w-6 h-6 en el icono de cabecera).
#       - Todos los onClick/onChange y sus handlers (navigate, goToday,
#         setPlanView, setViewMode, setObraSearch, setEstadoFilter,
#         setShowArchived, setPanelOpen) permanecen EXACTAMENTE iguales.
#       - Contenedor principal: h-[calc(100vh-7rem)] -> h-[calc(100vh-6rem)]
#         para aprovechar el espacio liberado por la cabecera mas compacta;
#         el grid interior sigue siendo flex-1 min-h-0 con su propio
#         overflow-auto, por lo que no hay riesgo de desbordamiento.
#
# NO SE HA MODIFICADO NINGUNA LOGICA FUNCIONAL:
#   drag & drop, reordenacion de obras, asignaciones, permisos, filtros,
#   cambio de semana, Vista Personas, vista movil, resaltado de dia actual,
#   resaltado de fila/columna/celda durante el arrastre, validaciones de
#   disponibilidad y conflictos. Todo verificado via diff (ver mensaje del
#   asistente) comparando handlers antes/despues.
#
# AUDIT LOG: no aplica (cambio puramente visual, no toca tablas, endpoints,
# formularios ni modulos nuevos).
#
# EJECUCION: no requiere migracion SQL ni pasos manuales en Supabase.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR: no se encuentra $RepoPath" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> fix: optimizar espacio visual del Planificador (nombre+estado en linea, cabecera compacta)" -ForegroundColor Cyan

Write-Host "  -> src\app\planificacion\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\planificacion\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\planificacion\page.tsx"), $bytes)
Write-Host "  OK: 76 KB" -ForegroundColor Green

$page = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\planificacion\page.tsx"), [System.Text.Encoding]::UTF8)
if ($page.Contains('title={obra.nombre}'))                            { Write-Host "  OK: tooltip con nombre completo de la obra" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains('max-w-[86px] truncate whitespace-nowrap'))        { Write-Host "  OK: estado en una sola linea, truncado" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains('min-h-[36px]'))                                    { Write-Host "  OK: altura de fila reducida (consistente)" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains('flex flex-wrap items-center justify-between gap-x-3 gap-y-1 mb-1.5')) { Write-Host "  OK: cabecera compactada en barra flex-wrap" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains('onChangeEstado(obra.id, e.target.value)'))        { Write-Host "  OK: logica de cambio de estado intacta" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }

Write-Host ""
Write-Host "  No requiere migracion SQL ni pasos manuales en Supabase." -ForegroundColor Yellow
Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "fix: optimizar espacio visual del Planificador (nombre+estado en linea, cabecera compacta)"'
Write-Host "  git push"
Write-Host ""
Write-Host "  Despues del deploy: Vercel -> Deployments -> ... -> Promote to Production" -ForegroundColor Yellow
